import type { ActionContext } from "../../core/action-context.ts";
import type { SendReactionInput } from "../../models/messaging.ts";
import { sendE2EEReactionAction } from "./send-e2ee-reaction.action.ts";

export async function sendReactionAction(ctx: ActionContext, input: SendReactionInput): Promise<void> {
  const isE2EE = ctx.isE2EEThreadId(input.threadId);

  let isE2EEConnected = true;
  try {
    ctx.requireE2EESocket();
  } catch {
    isE2EEConnected = false;
  }

  if (isE2EEConnected && isE2EE) {
    await sendE2EEReactionAction(
      ctx,
      input.threadId,
      input.messageId,
      input.reaction,
      input.senderJid ?? input.targetSenderJid,
    );
    return;
  }

  // Fallback: fca-unofficial plaintext reaction (non-E2EE threads)
  await ctx.messagingService.react(ctx.requireApi(), input);
}
