import type { MediaUploadConfig, MediaUploadResult, MmsTypeStr } from "../../models/media.ts";
export type { MediaUploadConfig, MediaUploadResult, MmsTypeStr };

export function toMediaUploadToken(fileEncSHA256: Buffer): string {
  return fileEncSHA256.toString("base64").replace(/\+/g, "-").replace(/\//g, "_");
}

/**
 * Callback to refresh media upload config (e.g., re-query media_conn).
 */
export type RefreshUploadConfigFn = () => Promise<MediaUploadConfig>;

export interface UploadMediaOptions {
  /** Optional callback to refresh auth config on 401. */
  refreshConfig?: RefreshUploadConfigFn;
  /** Max retry attempts after refresh (default 1). */
  maxRetries?: number;
}

/**
 * Upload encrypted media bytes to Facebook's upload CDN.
 * Supports retry on 401 by refreshing the upload config.
 */
export async function uploadMedia(
  config: MediaUploadConfig,
  data: Buffer,
  fileEncSHA256: Buffer,
  mmsType: MmsTypeStr,
  options?: UploadMediaOptions,
): Promise<MediaUploadResult> {
  if (!config.auth) {
    throw new Error("Missing media upload auth token; query media_conn before uploading E2EE media");
  }

  const token = toMediaUploadToken(fileEncSHA256);
  const maxRetries = options?.maxRetries ?? 1;
  let currentConfig = config;
  const unreachableHosts: string[] = [];

  // Preferred host first, then the remaining media_conn hosts, then the
  // well-known default. A host that fails at the network level is skipped.
  const candidateHosts = (): string[] => {
    const list = [currentConfig.host, ...(currentConfig.hosts ?? []), "rupload.facebook.com"];
    const seen = new Set<string>();
    return list.filter((h) => !!h && !seen.has(h) && (seen.add(h), true));
  };

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    let refreshed = false;
    for (const host of candidateHosts()) {
      const uploadUrl = `https://${host}/wa-msgr/mms/${mmsType}/${token}?auth=${encodeURIComponent(currentConfig.auth)}&token=${encodeURIComponent(token)}`;

      let resp: Response;
      try {
        // No manual Content-Length: undici sets the correct value for Buffer
        // bodies itself. A hand-written one was rejected as an "invalid
        // content-length header" on some networks/hosts.
        resp = await fetch(uploadUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/octet-stream",
            "Origin": "https://www.facebook.com",
            "Referer": "https://www.facebook.com/",
          },
          body: data,
        });
      } catch (err) {
        // Node fetch failures carry the real reason (DNS/TLS/connect) on `cause`.
        const cause = (err as { cause?: unknown })?.cause;
        const reason = cause instanceof Error ? cause.message
          : cause != null ? String(cause)
          : err instanceof Error ? err.message : String(err);
        unreachableHosts.push(`${host} (${reason})`);
        console.warn(`Media upload host unreachable: ${host} (${reason}) — trying next host`);
        continue;
      }

      if (resp.ok) {
        const json = await resp.json() as Record<string, unknown>;
        const stringField = (...keys: string[]): string => {
          for (const key of keys) {
            const value = json[key];
            if (typeof value === "string") return value;
            if (typeof value === "number") return String(value);
          }
          return "";
        };

        const directPath = stringField("direct_path", "directPath");
        if (!directPath) {
          throw new Error(
            `Media upload response missing direct_path (got keys: ${Object.keys(json).join(",") || "<empty>"})`
          );
        }

        return {
          url: stringField("url"),
          directPath,
          handle: stringField("handle"),
          objectId: stringField("object_id", "objectID", "objectId"),
        };
      }

      // On 401, try to refresh config and retry with the fresh hosts
      if (resp.status === 401 && attempt < maxRetries && options?.refreshConfig) {
        const body = await resp.text().catch(() => "");
        console.warn(`Media upload 401 (attempt ${attempt + 1}), refreshing config...`, body.slice(0, 200));
        currentConfig = await options.refreshConfig();
        if (!currentConfig.auth) {
          throw new Error("Media upload refresh returned empty auth token");
        }
        refreshed = true;
        break;
      }

      // Non-401 or max retries exceeded
      const body = await resp.text().catch(() => "");
      throw new Error(`Media upload failed: HTTP ${resp.status} on ${host} - ${body.slice(0, 500)}`);
    }

    if (refreshed) continue;
    if (unreachableHosts.length > 0) {
      throw new Error(`Media upload failed: all hosts unreachable (${unreachableHosts.join(", ")})`);
    }
  }

  // Should not reach here, but just in case
  throw new Error("Media upload failed after retries");
}
